// Voice gate for text written into the site database (DR-287): the seven site MCP write tools and
// the admin API. It runs on Vercel, so it uses the JavaScript port of the Spark voice check
// (voicecheck/check.mjs at the repo root, patterns exported from brain/voicecheck into
// voicecheck/voicecheck.json, both generated by brain-server): long dashes, invisible
// characters, look-alike letters and the short signature tells. It does not run the long-text
// statistics; on the Spark the voice-gate hook does that for Spark sessions before this ever runs.
//
// Same semantics as every other gate: block refuses with the findings, flag lets the write through
// with a note, and an explicit override carrying a reason passes and is logged (gate-log.ts).
// An update is judged on what it ADDS: a finding that already sat in the stored text, on the same
// line, does not block an edit elsewhere in that text. Create and publish judge the whole text.

import { createHash } from "node:crypto";
// the checker sits outside src: it is the tell catalogue, and every copy check would read it as copy
import data from "../../../voicecheck/voicecheck.json";
import { createChecker } from "../../../voicecheck/check.mjs";

export type Band = "pass" | "flag" | "block";

export interface Finding {
  tell: string;
  name: string;
  kind: "policy" | "signature";
  line: number;
  start: number;
  end: number;
  quote: string;
  why: string;
  fix: string;
}

interface Verdict {
  band: Band;
  score: number;
  language: string;
  words: number;
  coverage: boolean;
  signatures: number;
  findings: Finding[];
}

export interface FieldInput {
  field: string;
  text: string | null | undefined;
  // the stored value this write replaces; omit for a create or a publish
  before?: string | null;
}

export interface FieldResult {
  field: string;
  band: Band;
  findings: Finding[];
  coverage: boolean;
}

export interface GateResult {
  band: Band;
  fields: FieldResult[];
  sha: string;
}

export interface VoiceOverride {
  reason: string;
}

const checker = createChecker(data) as unknown as { check(text: string): Verdict; version: string };
const ORDER: Record<Band, number> = { pass: 0, flag: 1, block: 2 };
const PER_WORDS = data.short.per_words;
// built with the constructor: the tsconfig has no target, so the compiler rejects a u flag literal
const WHITESPACE = new RegExp("\\s+", "u");
const LETTER = new RegExp("\\p{L}", "u");

export const VOICE_VERSION = checker.version;

export function checkText(text: string): Verdict {
  return checker.check(text);
}

function lineKey(text: string, f: Finding): string {
  const a = f.start === 0 ? 0 : text.lastIndexOf("\n", f.start - 1) + 1;
  let b = text.indexOf("\n", f.end);
  if (b < 0) b = text.length;
  return `${f.tell}\n${text.slice(a, b).replace(/\s+/g, " ").trim()}`;
}

function bandFor(findings: Finding[], words: number, coverage: boolean): Band {
  if (findings.some((f) => f.tell === "dash")) return "block";
  const nSig = findings.filter((f) => f.kind === "signature").length;
  const nEff = words > PER_WORDS ? nSig * Math.min(1, PER_WORDS / words) : nSig;
  if (nEff >= 2) return "block";
  if (nEff >= 1) return "flag";
  if (coverage || findings.some((f) => f.kind === "policy")) return "flag";
  return "pass";
}

export function checkField(input: FieldInput): FieldResult {
  const text = input.text ?? "";
  if (!text.trim()) return { field: input.field, band: "pass", findings: [], coverage: false };
  const v = checker.check(text);
  let findings = v.findings;
  let coverage = v.coverage;
  if (input.before && input.before.trim()) {
    const old = checker.check(input.before);
    const budget = new Map<string, number>();
    for (const f of old.findings) {
      const k = lineKey(input.before, f);
      budget.set(k, (budget.get(k) ?? 0) + 1);
    }
    findings = v.findings.filter((f) => {
      const k = lineKey(text, f);
      const n = budget.get(k) ?? 0;
      if (n > 0) {
        budget.set(k, n - 1);
        return false;
      }
      return true;
    });
    coverage = v.coverage && !old.coverage;
  }
  return { field: input.field, band: bandFor(findings, v.words, coverage), findings, coverage };
}

export function textSha(texts: string[]): string {
  const norm = texts.join("\n").split(WHITESPACE).filter(Boolean).join(" ");
  return createHash("sha256").update(norm, "utf8").digest("hex");
}

export function checkFields(inputs: FieldInput[]): GateResult {
  const fields = inputs.filter((i) => typeof i.text === "string" && i.text.trim()).map(checkField);
  let band: Band = "pass";
  for (const f of fields) if (ORDER[f.band] > ORDER[band]) band = f.band;
  return { band, fields, sha: textSha(inputs.map((i) => i.text ?? "")) };
}

// keys whose values are never copy (links, ids, image paths, layout switches)
const SKIP_KEYS = new Set([
  "href", "url", "src", "image", "imageId", "imageUrl", "heroImage", "heroImageId", "slug", "id", "icon",
  "kind", "variant", "color", "className", "videoId", "youtubeId", "sku", "productId", "price", "currency",
  "region", "type", "layout", "align", "theme", "path", "pathname", "filename", "embed", "link", "ctaHref",
  "ctaLink", "buttonHref", "linkUrl", "learnMoreUrl", "categorySlug", "categoryIcon", "width", "height",
]);

function looksLikeData(s: string): boolean {
  const t = s.trim();
  if (!LETTER.test(t)) return true;
  if (t.includes("://") || t.startsWith("/") || t.startsWith("#") || t.startsWith("mailto:")) return true;
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(t)) return true;
  if (!/\s/.test(t) && /[/_]|\.(png|jpe?g|webp|svg|gif|mp4|pdf)$/i.test(t)) return true;
  return false;
}

// Every copy string inside a JSON value, by path ("data.items[2].title").
export function textLeaves(value: unknown, prefix: string): Map<string, string> {
  const out = new Map<string, string>();
  const walk = (v: unknown, path: string, key: string | null) => {
    if (typeof v === "string") {
      if (!(key && SKIP_KEYS.has(key)) && !looksLikeData(v)) out.set(path, v);
    } else if (Array.isArray(v)) {
      v.forEach((x, i) => walk(x, `${path}[${i}]`, key));
    } else if (v && typeof v === "object") {
      for (const [k, x] of Object.entries(v as Record<string, unknown>)) walk(x, `${path}.${k}`, k);
    }
  };
  walk(value, prefix, null);
  return out;
}

// Field inputs for a JSON value, each leaf compared with the leaf at the same path before.
export function leafInputs(after: unknown, before: unknown, prefix: string): FieldInput[] {
  const a = textLeaves(after, prefix);
  const b = before === undefined ? new Map<string, string>() : textLeaves(before, prefix);
  return Array.from(a, ([field, text]) => ({ field, text, before: b.get(field) ?? null }));
}

export function readOverride(raw: unknown): VoiceOverride | null {
  if (!raw || typeof raw !== "object") return null;
  const reason = (raw as { reason?: unknown }).reason;
  if (typeof reason !== "string" || reason.trim().length < 8) return null;
  return { reason: reason.trim().slice(0, 500) };
}

function cut(s: string, n: number): string {
  const t = s.replace(/\s+/g, " ").trim();
  return t.length <= n ? t : t.slice(0, n).replace(/\s+\S*$/, "") + " ...";
}

function findingLines(r: GateResult, only: Band[], limit: number): string[] {
  const lines: string[] = [];
  for (const f of r.fields) {
    if (!only.includes(f.band)) continue;
    for (const x of f.findings) {
      if (lines.length >= limit) return lines;
      lines.push(`- ${f.field} L${x.line}: "${cut(x.quote, 120)}" -> ${x.name}: ${cut(x.fix, 150)}`);
    }
    if (f.coverage && !f.findings.length && lines.length < limit) {
      lines.push(`- ${f.field}: most of the text sits in quotes, dialogue lines or meta sections, so it could not be read`);
    }
  }
  return lines;
}

function what(r: GateResult): string {
  const blocked = r.fields.filter((f) => f.band === "block");
  const dash = blocked.some((f) => f.findings.some((x) => x.tell === "dash"));
  const voice = blocked.some((f) => f.findings.some((x) => x.kind === "signature"));
  if (dash && voice) return "has a long dash (house rule: never in anything that goes out) and reads as AI-written";
  if (dash) return "has a long dash (house rule: never in anything that goes out)";
  return "reads as AI-written";
}

// The refusal an MCP caller reads (it rewrites and calls again).
export function refusalText(tool: string, r: GateResult): string {
  return [
    `VOICE GATE: not saved (${tool}). The text ${what(r)}. Rewrite these lines the way Jesper would say them and call the tool again:`,
    ...findingLines(r, ["block"], 8),
    "No surface dodges (a swapped synonym, a sprinkled 'really'): rewrite the line.",
    'Only if Jesper explicitly approved this exact text: call again with voiceOverride: { reason: "<what he said>" }. It is logged. Never on your own.',
  ].join("\n");
}

// The note appended to a write that went through on a flag.
export function flagText(r: GateResult): string {
  return [
    "VOICE GATE (advisory, saved anyway): parts of this text read as AI-written. Consider rewriting before it is published:",
    ...findingLines(r, ["flag"], 4),
  ].join("\n");
}

// The JSON body of an admin refusal (HTTP 422); the admin editor shows it and asks for a reason.
export function refusalBody(r: GateResult) {
  return {
    error: `Voice check: this text ${what(r)}. Fix the lines below, or save anyway with a reason.`,
    voice: {
      band: r.band,
      findings: r.fields.flatMap((f) =>
        f.findings.map((x) => ({ field: f.field, line: x.line, name: x.name, quote: cut(x.quote, 140), fix: cut(x.fix, 160) })),
      ),
    },
  };
}

// A short summary for the log row: which fields, which tells.
export function summary(r: GateResult) {
  return r.fields
    .filter((f) => f.band !== "pass")
    .map((f) => ({ field: f.field, band: f.band, tells: f.findings.map((x) => x.tell), coverage: f.coverage }));
}
